"""Changelog and version files from Conventional Commit messages. See task.md."""

from __future__ import annotations

import pathlib
import re


class CommitError(ValueError):
    """Raised when `previous_version` is not a valid `X.Y.Z` version."""


def _validate_version(version: str) -> None:
    """Validate that version is in X.Y.Z format."""
    parts = version.split(".")
    if len(parts) != 3:
        raise CommitError(f"Invalid version: {version}")

    for part in parts:
        if not part or not part.isdigit():
            raise CommitError(f"Invalid version: {version}")
        if len(part) > 1 and part[0] == "0":
            raise CommitError(f"Invalid version: {version}")


def _parse_commit(msg: str) -> dict | None:
    """Parse a commit message into its components."""
    parts = msg.split("\n\n", 1)
    subject = parts[0].strip()
    body = parts[1].strip() if len(parts) > 1 else ""

    if "\n" in subject:
        return None

    match = re.match(r"^([a-z]+)(?:\(([^()]*)\))?(!)?:\s*(.+)$", subject)
    if not match:
        return None

    commit_type = match.group(1)
    scope = match.group(2)
    breaking_marker = match.group(3) is not None
    description = match.group(4).strip()

    if not description:
        return None

    if scope:
        scope = scope.strip()
        if not scope:
            scope = None

    breaking_in_body = False
    if body:
        for line in body.split("\n"):
            line = line.strip()
            if line.startswith("BREAKING CHANGE:") or line.startswith("BREAKING-CHANGE:"):
                breaking_in_body = True
                break

    is_breaking = breaking_marker or breaking_in_body

    return {
        "type": commit_type,
        "scope": scope,
        "description": description,
        "is_breaking": is_breaking,
    }


def _calculate_version(prev_version: str, commits: list[dict]) -> str:
    """Calculate new version based on commits."""
    parts = prev_version.split(".")
    major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

    has_breaking = any(c["is_breaking"] for c in commits)
    has_feat = any(c["type"] == "feat" and not c["is_breaking"] for c in commits)
    has_fix_or_perf = any(
        c["type"] in ("fix", "perf") and not c["is_breaking"] for c in commits
    )

    if has_breaking:
        major += 1
        minor = 0
        patch = 0
    elif has_feat:
        minor += 1
        patch = 0
    elif has_fix_or_perf:
        patch += 1

    return f"{major}.{minor}.{patch}"


def _format_entry(scope: str | None, description: str) -> tuple[str | None, str]:
    """Format a changelog entry, return (scope, formatted_line) for sorting."""
    if scope:
        return (scope, f"- **{scope}**: {description}")
    else:
        return (None, f"- {description}")


def _sort_entries(entries: list[tuple[str | None, str]]) -> list[str]:
    """Sort entries by scope (non-None first), then by description."""
    with_scope = [e for e in entries if e[0] is not None]
    without_scope = [e for e in entries if e[0] is None]

    with_scope.sort(key=lambda x: (x[0], x[1]))
    without_scope.sort(key=lambda x: x[1])

    return [e[1] for e in with_scope] + [e[1] for e in without_scope]


def _build_changelog(version: str, commits: list[dict]) -> str:
    """Build the CHANGELOG.md content."""
    breaking_entries = []
    feature_entries = []
    fix_entries = []
    perf_entries = []

    for commit in commits:
        commit_type = commit["type"]
        scope = commit["scope"]
        description = commit["description"]
        is_breaking = commit["is_breaking"]

        entry = _format_entry(scope, description)

        if is_breaking:
            breaking_entries.append(entry)
        elif commit_type == "feat":
            feature_entries.append(entry)
        elif commit_type == "fix":
            fix_entries.append(entry)
        elif commit_type == "perf":
            perf_entries.append(entry)

    def deduplicate_and_sort(entries):
        if not entries:
            return []
        seen = set()
        unique_entries = []
        for entry in entries:
            if entry[1] not in seen:
                seen.add(entry[1])
                unique_entries.append(entry)
        return _sort_entries(unique_entries)

    breaking = deduplicate_and_sort(breaking_entries)
    features = deduplicate_and_sort(feature_entries)
    fixes = deduplicate_and_sort(fix_entries)
    perf = deduplicate_and_sort(perf_entries)

    lines = [f"## {version}"]

    if breaking:
        lines.append("")
        lines.append("### Breaking changes")
        lines.append("")
        lines.extend(breaking)

    if features:
        lines.append("")
        lines.append("### Features")
        lines.append("")
        lines.extend(features)

    if fixes:
        lines.append("")
        lines.append("### Fixes")
        lines.append("")
        lines.extend(fixes)

    if perf:
        lines.append("")
        lines.append("### Performance")
        lines.append("")
        lines.extend(perf)

    return "\n".join(lines) + "\n"


def build(commits: list[str], previous_version: str, out_dir: str) -> None:
    """Write `<out_dir>/CHANGELOG.md` and `<out_dir>/version.txt`."""
    _validate_version(previous_version)

    parsed_commits = []
    for commit_msg in commits:
        parsed = _parse_commit(commit_msg)
        if parsed:
            parsed_commits.append(parsed)

    new_version = _calculate_version(previous_version, parsed_commits)
    changelog_content = _build_changelog(new_version, parsed_commits)

    out_path = pathlib.Path(out_dir)
    out_path.mkdir(parents=True, exist_ok=True)

    (out_path / "CHANGELOG.md").write_text(changelog_content, encoding="utf-8")
    (out_path / "version.txt").write_text(new_version + "\n", encoding="utf-8")
